import { Controller } from "@hotwired/stimulus"

// Dedicated TinyMCE controller - handles initialization and cleanup
export default class extends Controller {
  connect() {
    this.loadTinyMCE()
  }

  disconnect() {
    this.destroyEditor()
    this.disconnectVisibilityObserver()
  }

  loadTinyMCE() {
    // Check if TinyMCE is already loaded
    if (window.tinymce) {
      this.initEditor()
      this.setupVisibilityObserver()
      return
    }

    // Load TinyMCE from CDN
    const apiKey = this.getApiKey()
    const script = document.createElement('script')
    script.src = `https://cdn.tiny.cloud/1/${apiKey}/tinymce/8/tinymce.min.js`
    script.referrerPolicy = 'origin'

    script.onload = () => {
      console.log('TinyMCE loaded from CDN')
      this.initEditor()
      this.setupVisibilityObserver()
    }

    script.onerror = () => {
      console.error('Failed to load TinyMCE from CDN')
    }

    document.head.appendChild(script)
  }

  getApiKey() {
    // Try to get API key from meta tag
    const metaTag = document.querySelector('meta[name="tinymce-api-key"]')
    if (metaTag) {
      return metaTag.getAttribute('content') || 'no-api-key'
    }
    return 'no-api-key'
  }

  setupVisibilityObserver() {
    // Watch for visibility changes on parent elements
    this.visibilityObserver = new MutationObserver(() => {
      // If element becomes visible and TinyMCE is not initialized, init it
      if (this.element.offsetParent && !tinymce.get(this.element.id)) {
        console.log('Element became visible, initializing TinyMCE:', this.element.id)
        this.initEditor()
      }
    })

    // Observe class changes on parent elements (for hidden/show toggles)
    let parent = this.element.parentElement
    while (parent) {
      this.visibilityObserver.observe(parent, {
        attributes: true,
        attributeFilter: ['class']
      })
      parent = parent.parentElement
      // Stop at form level to avoid too many observers
      if (parent?.tagName === 'FORM') break
    }
  }

  disconnectVisibilityObserver() {
    if (this.visibilityObserver) {
      this.visibilityObserver.disconnect()
    }
  }

  initEditor() {
    // Skip if already initialized
    if (tinymce.get(this.element.id)) {
      console.log('TinyMCE already initialized for:', this.element.id)
      return
    }

    // Skip if element is not visible
    if (!this.element.offsetParent) {
      console.log('Element not visible, will init when visible:', this.element.id)
      return
    }

    console.log('Initializing TinyMCE for:', this.element.id)

    // Initialize TinyMCE with default config
    tinymce.init({
      target: this.element,
      menubar: false,
      plugins: 'lists link',
      toolbar: 'undo redo | bold italic underline | bullist numlist',
      height: 300,
      setup: (editor) => {
        editor.on('init', () => {
          console.log('TinyMCE ready:', this.element.id)
        })
      }
    }).catch(error => {
      console.error('TinyMCE initialization failed:', error)
    })
  }

  destroyEditor() {
    try {
      const editor = tinymce.get(this.element.id)
      if (editor) {
        console.log('Destroying TinyMCE editor:', this.element.id)
        editor.remove()
      }
    } catch (error) {
      console.error('Error destroying TinyMCE editor:', error)
    }
  }

  // Public method to manually reinitialize (called when parent element becomes visible)
  reinit() {
    this.destroyEditor()
    // Small delay to ensure DOM is settled
    setTimeout(() => this.initEditor(), 50)
  }
}

