import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["input", "dropdown", "options"]
  static values = {
    categories: Array,
    field: String
  }

  connect() {
    this.loadCategories()
    this.setupEventListeners()
  }

  loadCategories() {
    // Hardcoded category options from Product enum
    this.categoriesValue = [
      'google_workspace',
      'olsera',
      'shopkey',
      'pasang_iklan'
    ]
    this.updateDropdownOptions()
  }

  setupEventListeners() {
    // Show dropdown when input is focused
    this.inputTarget.addEventListener('focus', () => {
      this.showDropdown()
    })

    // Hide dropdown when clicking outside
    document.addEventListener('click', (event) => {
      if (!this.element.contains(event.target)) {
        this.hideDropdown()
      }
    })

    // Filter categories as user types
    this.inputTarget.addEventListener('input', () => {
      this.filterCategories()
      this.updateFormData()
    })
  }

  updateDropdownOptions() {
    if (!this.hasOptionsTarget) return

    this.optionsTarget.innerHTML = ''

    // Show only hardcoded enum categories
    this.categoriesValue.forEach(category => {
      const option = document.createElement('div')
      option.className = 'px-4 py-2 hover:bg-gray-100 cursor-pointer border-b border-gray-100'
      option.textContent = category
      option.addEventListener('click', () => this.selectCategory(category))
      this.optionsTarget.appendChild(option)
    })
  }

  filterCategories() {
    const query = this.inputTarget.value.toLowerCase().trim()

    if (query === '') {
      this.updateDropdownOptions()
      return
    }

    // Filter categories that match the query (hardcoded enum only)
    const filteredCategories = this.categoriesValue.filter(category =>
      category.toLowerCase().includes(query)
    )

    this.optionsTarget.innerHTML = ''

    // Show only filtered enum categories
    filteredCategories.forEach(category => {
      const option = document.createElement('div')
      option.className = 'px-4 py-2 hover:bg-gray-100 cursor-pointer border-b border-gray-100'
      option.textContent = category
      option.addEventListener('click', () => this.selectCategory(category))
      this.optionsTarget.appendChild(option)
    })

    // Show "No results" if no matches
    if (filteredCategories.length === 0) {
      const noResults = document.createElement('div')
      noResults.className = 'px-4 py-2 text-gray-500 text-sm'
      noResults.textContent = 'No matching categories found'
      this.optionsTarget.appendChild(noResults)
    }
  }

  selectCategory(category) {
    // Only allow selection from hardcoded enum
    if (!this.categoriesValue.includes(category)) {
      return
    }

    this.inputTarget.value = category
    this.hideDropdown()
    this.updateFormData()
  }

  showDropdown() {
    if (this.hasDropdownTarget) {
      this.dropdownTarget.classList.remove('hidden')
      this.updateDropdownOptions()
    }
  }

  hideDropdown() {
    if (this.hasDropdownTarget) {
      this.dropdownTarget.classList.add('hidden')
    }
  }

  updateFormData() {
    // Trigger input event for form JSON update
    this.inputTarget.dispatchEvent(new Event('input', { bubbles: true }))
  }
}

import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["container", "template"]

  connect() {
    this.fieldCount = 0
    this.fields = []
    this.initializeExistingFields()
  }

  initializeExistingFields() {
    // Check if there are existing fields in the container
    const existingFields = this.containerTarget.querySelectorAll('[data-field-index]')
    this.fieldCount = existingFields.length

    // If no existing fields, add one empty field
    if (this.fieldCount === 0) {
      this.addField()
    }
  }

  addField() {
    const fieldHtml = `
      <div class="flex items-center space-x-2 mb-2" data-field-index="${this.fieldCount}">
        <input type="text"
               placeholder="Group"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="group">
        <input type="text"
               placeholder="Name"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="name">
        <input type="text"
               placeholder="Value"
               class="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
               data-action="input->dynamic-fields#updateField"
               data-field-type="value">
        <button type="button"
                class="text-red-500 hover:text-red-700 p-2"
                data-action="click->dynamic-fields#removeField">
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>
    `

    this.containerTarget.insertAdjacentHTML('beforeend', fieldHtml)
    this.fieldCount++
    this.updateJsonField()
  }

  removeField(event) {
    const fieldRow = event.target.closest('[data-field-index]')
    if (fieldRow) {
      fieldRow.remove()
      this.updateJsonField()
    }
  }

  updateField() {
    this.updateJsonField()
  }

  updateJsonField() {
    const groupedFields = {}
    const fieldRows = this.containerTarget.querySelectorAll('[data-field-index]')

    fieldRows.forEach(row => {
      const groupInput = row.querySelector('[data-field-type="group"]')
      const nameInput = row.querySelector('[data-field-type="name"]')
      const valueInput = row.querySelector('[data-field-type="value"]')

      const group = groupInput.value.trim()
      const name = nameInput.value.trim()
      const value = valueInput.value.trim()

      if (group && name && value) {
        // Initialize group array if doesn't exist
        if (!groupedFields[group]) {
          groupedFields[group] = []
        }

        // Add name-value pair to the group
        groupedFields[group].push({
          name: name,
          value: value
        })
      }
    })

    // Update the hidden field with JSON
    const hiddenField = document.querySelector('[name="product[specification_pdp]"]')
    if (hiddenField) {
      hiddenField.value = JSON.stringify(groupedFields)
      // Trigger input event to update main form JSON
      hiddenField.dispatchEvent(new Event('input', { bubbles: true }))
    }

    // Trigger custom event for the main form controller
    this.dispatch('fieldUpdated', { detail: { field: 'specification_pdp', value: groupedFields } })
  }
}

