FactoryBot.define do
  factory :product do
    sequence(:name) { |n| "Product #{n}" }
    description { Faker::Lorem.paragraph }
    price { Faker::Commerce.price(range: 10..100.0) }
    tax { [ 'exclude', 'include' ].sample }
    recurrence { [ 'mrc', 'otc' ].sample }
    status { [ 'draft', 'publish' ].sample }
    promo_code { Faker::Alphanumeric.alphanumeric(number: 6) }
    promo_code_child { Faker::Alphanumeric.alphanumeric(number: 6) }
    security_deposit { Faker::Commerce.price(range: 10..100.0) }
    specification { JSON.generate({ features: [ "Storage", "Bandwidth", "Email Support", "24/7 Support" ], benefits: [ "Unlimited Storage", "High Performance", "Secure Data" ] }) }
    quantity_range { [ 'q_1_9', 'q_1_25', 'q_1_49', 'q_1_99' ].sample }
    product_type { 'shared_quota' }
    member_limit { [ true, false ].sample }

    trait :draft do
      status { 'draft' }
    end

    trait :publish do
      status { 'publish' }
    end

    trait :with_member_limit do
      member_limit { true }
    end

    trait :with_specification do
      specification { JSON.generate({ features: [ "Feature 1", "Feature 2" ] }) }
    end

    trait :shared_quota do
      product_type { 'shared_quota' }
      tax { [ 'exclude', 'include' ].sample }
      recurrence { [ 'mrc', 'otc' ].sample }
      member_limit { [ true, false ].sample }
    end

    trait :fixed_quota do
      product_type { 'fixed_quota' }
      tax { [ 'exclude', 'include' ].sample }
      recurrence { [ 'mrc', 'otc' ].sample }
      member_limit { [ true, false ].sample }
    end

    trait :toko do
      product_type { 'toko' }
      tax { nil }
      recurrence { nil }
      member_limit { nil }
      category_product { [ 'google_workspace', 'olsera', 'shopkey', 'pasang_iklan' ].sample }
      overview { Faker::Lorem.paragraph(sentence_count: 5) }
      specification_pdp do
        {
          "General" => [
            { "name" => "Fitur 1", "value" => Faker::Lorem.sentence },
            { "name" => "Fitur 2", "value" => Faker::Lorem.sentence }
